{
  "market_version": 1,
  "name": "官方扩展",
  "description": "Persona 官方维护的扩展。",
  "extensions": [
    {
      "manifest": {
        "manifest_version": 1,
        "id": "agent-bypass-allow",
        "name": "Bypass 自动允许",
        "version": "0.2.31",
        "description": "Claude Code 或 Antigravity CLI（agy）开着 bypass 模式（Claude Code 的 bypassPermissions / --dangerously-skip-permissions，agy 的 always-proceed）时，有些调用仍会弹确认框（如读工作目录外的文件、开子 Agent、某些命令），无人值守的 Agent 就卡在「在等你」。在你选的电脑上给 Claude Code 和 agy 装一个本地 hook：只在会话是 bypass 模式时，自动允许命令执行（Bash / run_command）、只读工具（Read、Glob、Grep、LS、NotebookRead 等）和子 Agent。删除、覆盖数据的命令，目标都在临时目录或工作目录里（/tmp、会话的工作目录、~/ag-work、~/wt、Claude Code 的 worktree 等）时直接放行，其余的仍然问你；打开「删除和覆盖也自动允许」就都放行。force push、改权限的命令，写文件、Workflow 和 MCP 工具，以及你自己配的 ask / deny 规则，始终问你。每次自动允许都记一条（命令截断、去掉密钥）。别的模式照常问你。另有一个默认关的开关「Persona 助手对话的文件写入也自动允许」：打开后，Persona 的主对话和主管对话用 Write、Edit 写白名单目录（默认 ~/.jarvis/assistant 和 ~/.persona/assistant）里的文件时也直接放行，不论什么模式（计划模式除外）；其余照常问你。",
        "publisher": "nwverse",
        "homepage": "https://github.com/nwverse/persona-extensions/tree/main/extensions/agent-bypass-allow",
        "engines": {
          "persona": ">=202611041602",
          "extension_protocol": 1
        },
        "runtime": {
          "command": {
            "linux-amd64": "bin/agent-bypass-allow-linux-amd64",
            "linux-arm64": "bin/agent-bypass-allow-linux-arm64",
            "darwin-arm64": "bin/agent-bypass-allow-darwin-arm64",
            "darwin-amd64": "bin/agent-bypass-allow-darwin-amd64"
          },
          "args": [
            "hub"
          ]
        },
        "node": {
          "command": {
            "linux-amd64": "bin/agent-bypass-allow-linux-amd64",
            "linux-arm64": "bin/agent-bypass-allow-linux-arm64",
            "darwin-arm64": "bin/agent-bypass-allow-darwin-arm64",
            "darwin-amd64": "bin/agent-bypass-allow-darwin-amd64"
          },
          "args": [
            "node"
          ],
          "machines": "machines",
          "permissions": {
            "files": true
          }
        },
        "contributes": {
          "ui": [
            {
              "id": "log",
              "title": "自动允许记录",
              "placement": "extension_page"
            }
          ]
        },
        "configuration": {
          "type": "object",
          "properties": {
            "machines": {
              "type": "array",
              "title": "在哪些电脑上自动允许",
              "description": "打开的电脑上，Claude Code 的 settings.json 和 Antigravity CLI 的 config/hooks.json 里会装上本地 hook；关掉、停用或卸载扩展时去掉。",
              "items": {
                "type": "string",
                "format": "machine",
                "x-os": [
                  "darwin",
                  "linux"
                ]
              },
              "x-confirm": "这台电脑上 bypass 模式的 Claude Code 与 Antigravity CLI（agy）会话，命令执行、读文件（包括工作目录外的）和开子 Agent 的确认将不再问你、直接执行。删除、覆盖临时目录和工作目录里的东西也直接执行；别处的删除、覆盖，以及 force push、改权限仍然问你。每次都会记录。"
            },
            "allow_destructive": {
              "type": "boolean",
              "title": "删除和覆盖也自动允许",
              "description": "打开后，bypass 模式下删除、覆盖数据的 Bash 命令（rm、mv、git reset --hard、写进文件的 > 等）不管目标在哪都直接放行，包括家目录和工作目录以外的，删掉的可能找不回来。force push、改权限、格式化磁盘，以及你自己配的 ask / deny 规则仍然问你。关着时，只有目标都在临时目录、工作目录里的才放行。",
              "default": false
            },
            "config_dirs": {
              "type": "array",
              "title": "Claude Code 配置目录",
              "description": "装 Claude Code hook 的目录，~ 是那台电脑的家目录。用了 CLAUDE_CONFIG_DIR 的把那个目录也加上。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.claude"
              ]
            },
            "agy_dirs": {
              "type": "array",
              "title": "Antigravity CLI 配置目录",
              "description": "装 Antigravity CLI（agy）hook 的目录（写入其中的 config/hooks.json），~ 是那台电脑的家目录。默认 ~/.gemini 不存在时会自动跳过；用了自定义 --gemini-dir 的把那个目录也加上。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.gemini"
              ]
            },
            "assistant_writes": {
              "type": "boolean",
              "title": "Persona 助手对话的文件写入也自动允许",
              "description": "打开后，Persona 的主对话和主管对话（不是 bypass 模式）用 Write、Edit 写下面目录里的文件时直接放行，不再弹卡；计划模式除外。只认 Persona 启动的助手对话，普通 Agent 照常问你。目录里的 .claude、.gemini、.agents、.git 和 .mcp.json 等配置路径，目录外的路径，删除（走 Bash）、MultiEdit、NotebookEdit、联网写入，以及你自己配的 ask / deny 规则，照常问你。助手对话用的配置目录要在上面的配置目录里。",
              "default": false
            },
            "assistant_write_dirs": {
              "type": "array",
              "title": "助手对话可直接写入的目录",
              "description": "打开上一项后，助手对话写这些目录里（含子目录）的文件不再问你。~ 是那台电脑的家目录；经过链接和 .. 走到目录外的不算。",
              "items": {
                "type": "string",
                "minLength": 1,
                "maxLength": 512
              },
              "maxItems": 8,
              "default": [
                "~/.jarvis/assistant",
                "~/.persona/assistant"
              ]
            }
          }
        }
      },
      "tags": [
        "claude-code",
        "antigravity",
        "agents",
        "permissions"
      ],
      "replaces": "claude-bypass-allow",
      "icon": "assets/icon.png",
      "packages": [
        {
          "url": "oci:ghcr.io/nwverse/persona-extensions/agent-bypass-allow@sha256:43d430197a20146f62c6b438cf66d3f8a33275d73781e72b68eb63529b9c343a",
          "sha256": "f0e340d0643450258e4935d4128380a1be923f645805ed929790e8e7da308979",
          "size": 13592450
        }
      ],
      "icon_url": "https://raw.githubusercontent.com/nwverse/persona-extensions/1eb12f6b62d619d50fe148b72e99145bbf15dcda/extensions/agent-bypass-allow/assets/icon.png",
      "downloads": 516
    },
